/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
        if (scwin.contnId === "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07211.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        if (dts_fileList.getRowCount() === 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            if (scwin.contnId === "input") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
                file_name.setValue(inf_find.getValue());
            }
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07211.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name dts_ContentsInfo_OnLoadError
 * @description dts_ContentsInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_ContentsInfo.OnLoadError()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07211.dts_ContentsInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ContentsInfo_OnLoadCompleted
 * @description dts_ContentsInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gRegEmpNo = dts_ContentsInfo.getCellData(0, "WRTR_ID");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07211.dts_ContentsInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_fileList_OnClick
 * @description grd_fileList 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07211.grd_fileList_OnClick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        if (scwin.contnId === "input") {
            await scwin.save();
        } else {
            await scwin.update();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07211.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07211.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07211.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07211.btn_cancel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/lstinvstg/ListCommBoard.do",
        ref : "dts_ContentsInfo,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (dts_fileList.getCellData(1, "fileInfo") === "") {
        dts_fileList.Reset();
    }
    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    let rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_ContentsInfo.setCellData(1, "ANS_OBJ_CONTN_ID", "0");
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_BBS_TP_CD", scwin.bbsTypeCd); // 게시판구분
        dts_ContentsInfo.setCellData(1, "QUES_BZ_TP_CD", "1");
        dts_ContentsInfo.setCellData(1, "WRTR_ID", js_emp_no);
        dts_ContentsInfo.setCellData(1, "ISUR_CD", js_dep_cd);
        dts_ContentsInfo.setCellData(1, "REG_TEL_NO", "");
        dts_ContentsInfo.setCellData(1, "WRTR_EMAIL", js_email);
        dts_ContentsInfo.setCellData(1, "QUES_ANS_TP_CD", "1"); // 질문답변구분코드 : 1상장
        dts_ContentsInfo.setCellData(1, "LD_MKT_TP_CD", js_market); // 시장구분 : 1유가, 2코스닥
        dts_ContentsInfo.setCellData(1, "LIST_TP_CLSS_CD", ""); // 상장유형(가이드북)
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_FAQ_CLSS_CD", ""); // FAQ유형(FAQ)

        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/lstinvstg/ListCommBoard.do",
            ref : "dts_ContentsInfo,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (js_emp_no !== scwin.gRegEmpNo) {
        await $c.win.alert("게시물 등록자만  수정처리 할 수 있습니다.");
        return false;
    }
    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    let rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_ContentsInfo.setCellData(1, "ANS_OBJ_CONTN_ID", "0");
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_BBS_TP_CD", scwin.bbsTypeCd); // 게시판구분
        dts_ContentsInfo.setCellData(1, "QUES_BZ_TP_CD", "1");
        dts_ContentsInfo.setCellData(1, "WRTR_ID", js_emp_no);
        dts_ContentsInfo.setCellData(1, "ISUR_CD", js_dep_cd);
        dts_ContentsInfo.setCellData(1, "REG_TEL_NO", "");
        dts_ContentsInfo.setCellData(1, "WRTR_EMAIL", js_email);
        dts_ContentsInfo.setCellData(1, "QUES_ANS_TP_CD", "1"); // 질문답변구분코드 : 1상장
        dts_ContentsInfo.setCellData(1, "LD_MKT_TP_CD", js_market); // 시장구분 : 1유가, 2코스닥
        dts_ContentsInfo.setCellData(1, "LIST_TP_CLSS_CD", ""); // 상장유형(가이드북)
        dts_ContentsInfo.setCellData(1, "LIST_INVSTG_FAQ_CLSS_CD", ""); // FAQ유형(FAQ)

        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/lstinvstg/ListCommBoard.do",
            ref : "dts_ContentsInfo,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (js_emp_no !== scwin.gRegEmpNo) {
        await $c.win.alert("게시물 등록자만 삭제처리 할 수 있습니다.");
        return false;
    }
    let rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_ContentsDel.insertRow();
        dts_ContentsDel.setCellData(1, "CONTN_ID", scwin.contnId);
        // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     CONTN_ID : scwin.contnId
        // };
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/lstinvstg/ListCommBoard.do",
            ref : "dts_ContentsDel",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name setSaveHeader
 * @description set Save Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSaveHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_ContentsInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_ContentsInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_ContentsInfo.insertRow();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setFileDataHeader
 * @description set File Data Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setFileDataHeader = function() {

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?CONTN_ID=" + scwin.contnId + "&CONTN_SEQ=" + attach_seq + "&gubun=26";
};

/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkMaxLength2
 * @description check Max Length2 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength2 = async function(obj, size, lbl) {
    let overLen = ($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
